   ],
   "flex": true
  },
  {
   "old": "Real-time analytics allowed for faster response times to urgent inquiries. The project worked because infrastructure, workflow design, and governance were developed as one connected system.",
   "new": "",
   "max_bytes": 190,
   "scope": "all",
   "where": [
